    stderr_lines = [
        re.sub(r"\s+", " ", raw_line).strip().lower()
        for raw_line in str(result.stderr or "").splitlines()
        if raw_line.strip()
    ]
    expected_error = f'error from server (notfound): pods "{pod}" not found'.lower()
    return len(stderr_lines) == 1 and stderr_lines[0] == expected_error


